pvals = {"mobile": 0.004, "desktop": 0.03, "tablet": 0.011, "новые": 0.008, "старые": 0.20}
items = sorted(pvals.items(), key=lambda x: x[1])
result = []
for i in range(len(items)):
    if items[i][1] >= 0.05 / (len(items) - i):
        break
    result.append(items[i][0])
